window.RTLBenchLSData.register("assets/d3b246c8c4a1698dc8b3257ee439b56af09800d5958c2ed94f7ee3c52668ea31.txt","# JasperGold SEC: sequential equivalence (golden vs revised RTL).\n# Placeholders replaced by verification_tools.run_sec_remote:\n#   mipi_dphy_transmitter.v0, mipi_dphy_transmitter.v1, mipi_dphy_transmitter, core_clk, -none\nset DESIGN_NAME_GOLDEN \"mipi_dphy_transmitter.v0\"\nset DESIGN_NAME \"mipi_dphy_transmitter.v1\"\nset TOP_NAME \"mipi_dphy_transmitter\"\n\n\nclear -all\ncheck_sec -analyze -spec -sv ./input/rtl/${DESIGN_NAME_GOLDEN}.v\ncheck_sec -analyze -imp -sv ./input/rtl/${DESIGN_NAME}.v\ncheck_sec -elaborate -spec -top ${TOP_NAME} -disable_auto_bbox\ncheck_sec -elaborate -imp -top ${TOP_NAME} -disable_auto_bbox\n# check_sec -setup clock -infer reset -none\ncheck_sec -setup \ncheck_sec -map -auto\nclock core_clk \nreset -none\ncheck_sec -gen\n# check_sec -prove -strategy design_style -design_style_type clock_gating\n# check_sec -prove\ncheck_sec -prove -strategy proof\n");
